namespace Taruck.CharacterCreation
{
    // Concise level-one effects paraphrased from the pinned PHB/XPHB reference.
    // Casting time, range and duration are transferred separately from structured metadata.
    internal static class CharacterBardSpellText
    {
        internal static string Effect(RulesEdition edition, string name)
        {
            bool modern = edition == RulesEdition.Rules2024;
            switch (name)
            {
                case "Bane": return "До трьох істот роблять ряткидок Харизми; за провалу віднімають 1к4 від атак і ряткидків.";
                case "Blade Ward": return modern
                    ? "Атакувальники віднімають 1к4 від кидків на влучання по тобі."
                    : "До кінця наступного ходу маєш опір дробильній, колючій та рубальній шкоді від атак зброєю.";
                case "Charm Person": return "Гуманоїд робить ряткидок Мудрості, з перевагою під час бою з тобою чи союзниками. За провалу він Зачарований; шкода від вас завершує ефект. Після завершення ціль знає про чари.";
                case "Color Spray": return "Істоти в конусі 15 футів роблять ряткидок Статури; за провалу Засліплені до кінця твого наступного ходу.";
                case "Comprehend Languages": return "Розумієш буквальний зміст мовлення й тексту, якого торкаєшся. Не розшифровує таємні повідомлення.";
                case "Dancing Lights": return "До чотирьох вогників дають тьмяне світло на 10 футів. Бонусною дією можна пересунути їх на 60 футів; тримай їх у межах 20 футів один від одного.";
                case "Disguise Self": return "Ілюзорно змінює зовнішність і речі на тобі; зріст можна змінити на 1 фут. Дотик видає ілюзію; перевірка Аналізу проти складності магії допомагає її розпізнати.";
                case "Dissonant Whispers": return "Ряткидок Мудрості: 3к6 психічної шкоди та реакцією втеча від тебе безпечним шляхом; за успіху лише половина шкоди.";
                case "Faerie Fire": return "У кубі 20 футів ряткидок Спритності або цілі світяться, не мають користі від невидимості, а видимі атаки по них мають перевагу.";
                case "Feather Fall": return "Реакція на падіння: до п’яти істот падають зі швидкістю 60 футів за раунд і не отримують шкоди від приземлення до завершення ефекту.";
                case "Friends": return modern
                    ? "Гуманоїд робить ряткидок Мудрості або Зачарований. У бою чи після повторного каста за 24 год ефект не діє; атака, шкода або примусовий ряткидок завершують його. Ціль дізнається про чари."
                    : "Перевага на перевірки Харизми проти однієї неворожої істоти. Після завершення вона дізнається про магію та стає ворожою.";
                case "Cure Wounds": return modern ? "Відновлює 2к8 + модифікатор Харизми ОЗ." : "Відновлює 1к8 + модифікатор Харизми ОЗ; не діє на нежить і конструктів.";
                case "Healing Word": return modern ? "Відновлює видимій істоті 2к4 + модифікатор Харизми ОЗ." : "Відновлює видимій істоті 1к4 + модифікатор Харизми ОЗ; не діє на нежить і конструктів.";
                case "Identify": return "Визначає властивості магічного предмета, заряди та потребу налаштування; для істоти показує чинні заклинання. Потрібна перлина вартістю 100 зм.";
                case "Illusory Script": return "Створює приховане повідомлення: вибрані істоти читають справжній текст, інші бачать інший або незрозумілий. Матеріали вартістю 10 зм витрачаються.";
                case "Light": return modern
                    ? "Предмет розміру Великий або менший, який ніхто не носить, світить яскраво на 20 футів і тьмяно ще на 20. Непрозоре покриття блокує світло."
                    : "Предмет до 10 футів світить яскраво на 20 футів і тьмяно ще на 20. Для предмета на ворожій істоті потрібен ряткидок Спритності.";
                case "Mage Hand": return "Примарна рука маніпулює речами в межах 30 футів і переносить до 10 фунтів. Не атакує й не активує магічні предмети; керування потребує дії.";
                case "Mending": return "Лагодить один розрив або злам предмета розміром до 1 фута. Не відновлює магічні властивості.";
                case "Message": return "Одна істота чує твій шепіт і може відповісти лише тобі. Магічна тиша та достатньо товсті перепони блокують повідомлення.";
                case "Minor Illusion": return "Створює звук або зображення предмета в кубі до 5 футів. Дотик видає зображення; дією й перевіркою Аналізу проти складності магії можна розпізнати ілюзію.";
                case "Prestidigitation": return "Дрібні магічні трюки: світло чи звук, запалення вогню, очищення, смак, температура або позначка. До трьох тривалих ефектів одночасно.";
                case "Silent Image": return "Створює рухоме зображення в кубі до 15 футів без звуку й запаху. Керування дією; дотик або успішний Аналіз проти складності магії розкривають ілюзію.";
                case "Sleep": return modern
                    ? "У сфері радіусом 5 футів ряткидок Мудрості або Недієздатність; повторний провал наприкінці наступного ходу спричиняє Непритомність. Шкода або дія союзника пробуджує."
                    : "Кинь 5к8: сума визначає запас ОЗ уражених істот у радіусі 20 футів, починаючи з найменших поточних ОЗ. Вони засинають; шкода чи дія пробуджує. Не діє на нежить та імунних до чарів.";
                case "Starry Wisp": return "Далекобійна атака заклинанням: 1к8 променистої шкоди. До кінця твого наступного ходу ціль світиться на 10 футів і не має користі від невидимості.";
                case "Tasha's Hideous Laughter": return modern
                    ? "Ряткидок Мудрості або ціль лежить долілиць і Недієздатна. Повторний ряткидок наприкінці кожного ходу й після шкоди; від шкоди з перевагою."
                    : "Ряткидок Мудрості або ціль лежить долілиць і Недієздатна. Повторний ряткидок щохідно й після шкоди; від шкоди з перевагою. Не діє за Інтелекту 4 чи менше.";
                case "Thunderclap": return "Істоти в межах 5 футів роблять ряткидок Статури; за провалу 1к6 громової шкоди. Звук чутно за 100 футів.";
                case "Thunderwave": return "У кубі 15 футів від тебе ряткидок Статури: 2к8 громової шкоди й відштовхування на 10 футів; за успіху половина шкоди без відштовхування.";
                case "True Strike": return modern
                    ? "Одна атака зброєю використовує характеристику магії для влучання й шкоди. Можна замінити тип шкоди на променистий."
                    : "Наступного ходу маєш перевагу на першу атаку по вибраній цілі, якщо концентрація триває.";
                case "Unseen Servant": return "Невидимий слуга виконує прості завдання, не атакує; КО 10, 1 ОЗ, Сила 2. Бонусною дією дай наказ і пересунь його до 15 футів; межа віддалення 60 футів.";
                case "Vicious Mockery": return modern
                    ? "Ряткидок Мудрості або 1к6 психічної шкоди й завада на наступну атаку до кінця наступного ходу цілі."
                    : "Ціль має чути тебе. Ряткидок Мудрості або 1к4 психічної шкоди й завада на наступну атаку до кінця наступного ходу цілі.";
                default: return "";
            }
        }
    }
}
